function selectNeuralNode(event){var canvas=$('neuralCanvas'),scene=state.neuralScene;if(!canvas||!scene||!scene.projected)return;var rect=canvas.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top,best=null;Object.keys(scene.projected).forEach(function(id){var item=scene.projected[id],distance=Math.hypot(item.point.x-x,item.point.y-y),hit=Math.max(13,(item.radius||5)+7);if(distance<hit&&(!best||distance<best.distance))best={id:id,distance:distance,item:item}});if(!best)return;state.neuralSelected=best.id;var links=(scene.edges||[]).filter(function(edge){return edge.source===best.id||edge.target===best.id}).sort(function(a,b){return b.weight-a.weight});var node=best.item.node,topics=(node.topics||[]).map(function(value){return '<span>#'+esc(value)+'</span>'}).join(''),concepts=(node.topic_concepts||[]).map(function(value){return '<span>'+esc(value)+'</span>'}).join('');$('neuralDetail').innerHTML='<h3>'+esc(node.label)+'</h3><p>'+esc(node.summary||'요약 정보 없음')+'</p><div class="score-parts"><span>'+esc(node.article_type||'기타')+'</span><span>'+esc(node.tone||'사실전달')+'</span><span>케이스 점수 '+Number(node.score||0).toFixed(1)+'</span></div><p><b>상위 주제</b></p><div class="score-parts">'+(concepts||'<span>의미 벡터로 관계 분석</span>')+'</div><p><b>직접 주제 명사</b></p><div class="score-parts">'+(topics||'<span>추출된 주제 명사 없음</span>')+'</div><p><b>주제 연결 '+links.length+'개</b></p><ul>'+links.slice(0,8).map(function(edge){var other=edge.source===best.id?scene.nodeMap[edge.target]:scene.nodeMap[edge.source],shared=(edge.shared_concepts||edge.shared_topics||[]).join(', '),kind=edge.relation_level==='abstract_topic'?'상위':'직접';return '<li>'+esc(other&&other.label||'기사')+' · '+kind+' '+Math.round(edge.weight*100)+'%'+(shared?' · '+esc(shared):'')+'</li>'}).join('')+'</ul>';drawNeural()}
