  function providerLabel(provider,platform){provider=provider||{};var status=provider.exhausted?'무료 사용량 잠금':(provider.quota_probe_in_flight?'사용량 재확인 중':(provider.quota_recheck_due?'사용량 재확인 가능':(provider.available?'사용 가능':(provider.connected===false?'연결 필요':'확인 중'))));return providerName(provider.provider||platform)+' · '+simpleModelName(provider.model)+' · '+status}
  function modelPairLabel(provider,slots){provider=provider||{};var chain=Array.isArray(provider.chain)?provider.chain:[provider],items=(slots||[]).map(function(slot){return chain.find(function(item){return item&&item.slot===slot})}).filter(Boolean);if(items.length<2)items=chain.filter(function(item){return item&&item.slot!=='single'&&item.slot!=='turbo'}).slice(0,2);return items.map(function(item){return simpleModelName(item.model)}).join(' + ')||simpleModelName(provider.model)}
