  var threshold=Number(queues.burst_start_threshold||5);setTurbo("commonTurboMark",Boolean(queues.common_turbo)||waiting(common)>=threshold);setTurbo("caseTurboMark",false);
  set("commonProviderMeta",modelPairLabel(commonProvider,["model1","model2"]));set("embeddingProviderMeta",providerLabel(embeddingProvider,"Ollama"));set("caseProviderMeta",modelPairLabel(caseProvider,["model1","model2"]));
  var operation=providers.operation||{},notice=$("operationNotice");
