function adminStatusText(status,defaultLimit){status=status||{};var limit=Number(status.soft_limit||defaultLimit||0),used=Number(status.attempts||0),period=status.period==='UTC day'?'UTC일':(status.period==='Pacific day'?'태평양일':'오늘'),base=(status.connected?'연결 성공':'연결 실패');if(status.error)base+=' · '+status.error;base+=' · '+period+' '+used.toLocaleString()+(limit?'/'+limit.toLocaleString():'')+'회';if(Number(status.tokens||0))base+=' · '+Number(status.tokens||0).toLocaleString()+'토큰';if(status.exhausted&&status.disabled_until)base+=' · 무료 사용량 소진 · '+(status.lock_mode==='exact_reset'?'정확 초기화 ':'초기화 불명확 · 재확인 ')+fmt(status.disabled_until);else if(status.quota_probe_in_flight)base+=' · 사용량 재확인 중';else if(status.quota_recheck_due)base+=' · 사용량 재확인 가능';else if(status.reset_at)base+=' · 다음 초기화 '+fmt(status.reset_at);else if(status.reset_label)base+=' · 초기화 '+status.reset_label;return base}
