function renderModelUsage(target,status){var el=typeof target==='string'?$(target):target;if(!el)return;status=status||{};var calls=Number(status.attempts||0),tokens=Number(status.tokens||0),units=Number(status.usage_units||0),tokenLimit=Number(status.token_soft_limit||0),requestLimit=Number(status.soft_limit||0),unitLimit=Number(status.usage_unit_limit||0),provider=String(status.provider||'').toLowerCase(),unmetered=provider==='nvidia'||provider==='ollama',meterValue=0,meterLimit=0,meterUnit='';if(!unmetered&&tokenLimit){meterValue=tokens;meterLimit=tokenLimit;meterUnit='토큰'}else if(!unmetered&&unitLimit){meterValue=units;meterLimit=unitLimit;meterUnit='뉴런'}else if(!unmetered&&requestLimit){meterValue=calls;meterLimit=requestLimit;meterUnit='회 호출'}var ratio=meterLimit?Math.min(100,Math.round(meterValue/meterLimit*100)):0,label='현재: '+calls.toLocaleString()+'회 호출 / '+tokens.toLocaleString()+'토큰';if(Number(status.provider_model_count||0)>1)label+=' (플랫폼 총 '+Number(status.provider_total_attempts||0).toLocaleString()+'회 호출)';if(status.exhausted)label+=' · 사용량 소진';var maximum=provider==='nvidia'?'최대(40 RPM)':provider==='ollama'?'최대(무제한)':meterLimit?'최대('+meterLimit.toLocaleString()+' '+meterUnit+')':'최대(총량 미제공)';el.innerHTML='<span class="model-usage-label">'+esc(label)+'</span><span class="model-usage-value">'+esc(maximum)+'</span><span class="model-usage-track '+(!meterLimit?'unmetered':'')+'"><i style="width:'+ratio+'%"></i></span>'}
