async function loadAdminModelStatuses
(){var run=(state.adminModelStatusRun||0)+1;state.adminModelStatusRun=run;var targets=['common','case','common_fallback','case_fallback','case_single','burst','embedding'];targets.forEach(function(target){var el=$(adminModelStatusTarget(target));if(el)el.textContent=(el.textContent||'저장값 표시')+' · 확인 대기'});var promises=targets.map(async function(target){var el=$(adminModelStatusTarget(target));if(state.adminModelStatusRun!==run)return;if(el)el.textContent=(el.textContent||'저장값 표시').replace(/ · 확인 대기$/,'')+' · 상세 확인 중';try{var data=await req('/api/poc/master-press/admin/model-status?target='+encodeURIComponent(target));if(state.adminModelStatusRun!==run)return;applyAdminModelStatus(target,data)}catch(error){if(state.adminModelStatusRun!==run)return;var statusEl=$(adminModelStatusTarget(target));if(statusEl)statusEl.textContent='상세 확인 실패 · '+error.message}});await Promise.all(promises)}


function operationStatusLabel(value){return {active:'전환 적용 중',open:'확인 필요',retrying:'재시도 대기',resolved:'해소됨',pending:'대기',processing:'처리 중',failed:'실패',sent:'발송 완료'}[value]||value||'확인 필요'}
