function renderMiniTrend(target,items,series){
  var root=$(target);if(!root)return;items=items||[];series=series||[];var width=260,height=72,pad=12,values=[];
  series.forEach(function(key){items.forEach(function(item){values.push(Number(item[key]||0))})});var max=Math.max.apply(null,values.concat([1]));
  var lines=series.map(function(key,seriesIndex){var points=items.map(function(item,index){var x=pad+(width-pad*2)*(items.length<2?0:index/(items.length-1)),y=height-pad-(height-pad*2)*(Number(item[key]||0)/max);return x.toFixed(1)+','+y.toFixed(1)});return '<polyline class="'+(seriesIndex?'secondary':'')+'" points="'+points.join(' ')+'"></polyline>'+items.map(function(item,index){var point=points[index].split(','),value=Number(item[key]||0),labelY=Math.max(9,Math.min(height-2,Number(point[1])+(seriesIndex?12:-5)));return '<circle class="'+(seriesIndex?'secondary':'')+'" cx="'+point[0]+'" cy="'+point[1]+'" r="2"><title>'+esc(String(item.day||'').slice(5))+' · '+value.toLocaleString()+'건</title></circle><text class="chart-node-value '+(seriesIndex?'secondary':'')+'" x="'+point[0]+'" y="'+labelY.toFixed(1)+'" text-anchor="middle">'+value.toLocaleString()+'</text>'}).join('')}).join('');
  root.innerHTML='<svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="최근 7일 추이"><line x1="'+pad+'" x2="'+(width-pad)+'" y1="'+(height-pad)+'" y2="'+(height-pad)+'"></line>'+lines+'</svg>';
}
