function renderShadowDecisionTrend(items){var root=$('shadowDecisionTrend');if(!root)return;items=items||[];var width=320,height=116,padX=20,top=20,bottom=22,keys=['matching','different'],values=[];keys.forEach(function(key){items.forEach(function(item){values.push(Number(item[key]||0))})});var max=Math.max.apply(null,values.concat([1])),x=function(index){return padX+(width-padX*2)*(items.length<2?0:index/(items.length-1))},y=function(value){return top+(height-top-bottom)*(1-Number(value||0)/max)};var lines=keys.map(function(key,seriesIndex){var points=items.map(function(item,index){return x(index).toFixed(1)+','+y(item[key]).toFixed(1)}).join(' '),nodes=items.map(function(item,index){var value=Number(item[key]||0),px=x(index),py=y(value),labelY=seriesIndex?Math.min(height-bottom-2,py+13):Math.max(10,py-7);return '<circle class="'+key+'" cx="'+px.toFixed(1)+'" cy="'+py.toFixed(1)+'" r="3"><title>'+esc(item.day)+' · '+(seriesIndex?'불일치 ':'일치 ')+value.toLocaleString()+'건</title></circle><text class="chart-node-value '+key+'" x="'+px.toFixed(1)+'" y="'+labelY.toFixed(1)+'" text-anchor="middle">'+value.toLocaleString()+'</text>'}).join('');return '<polyline class="'+key+'" points="'+points+'"></polyline>'+nodes}).join('');var labels=items.map(function(item,index){return '<text x="'+x(index).toFixed(1)+'" y="'+(height-4)+'" text-anchor="middle">'+esc(String(item.day||'').slice(5).replace('-','/'))+'</text>'}).join('');root.innerHTML='<svg viewBox="0 0 '+width+' '+height+'" role="img" aria-label="최근 7일 그림자 판정 일치 및 불일치 추이"><line class="baseline" x1="'+padX+'" x2="'+(width-padX)+'" y1="'+(height-bottom)+'" y2="'+(height-bottom)+'"></line>'+lines+'<g class="axis-labels">'+labels+'</g></svg>'}
function renderShadowToggle(enabled){var button=$('shadowEnabledToggle');if(!button)return;var active=enabled!==false;button.classList.toggle('active',active);button.setAttribute('aria-pressed',active?'true':'false');button.setAttribute('aria-label',active?'그림자 판정 활성 상태, 누르면 비활성화':'그림자 판정 비활성 상태, 누르면 활성화');button.title=active?'활성':'비활성'}
