async function loadAdmin(force,loadingMessage,showOverlay){

  force=force!==false;
  var shouldShowLoading=showOverlay!==false;
  var cached=state.adminBootstrap;
  if(!force&&cached&&Date.now()-state.adminBootstrapAt<60000){
    state.isAdmin=true;$('adminGate').hidden=true;$('adminContent').hidden=false;
    renderAdmin(cached);scheduleAdminDetails();
    return;
  }
  if(shouldShowLoading)showLoading(loadingMessage||'관리 설정을 불러오는 중입니다...');
  try{
    await req('/api/admin/session');
    state.isAdmin=true;
    $('adminGate').hidden=true;
    $('adminContent').hidden=false;
    var data=await req('/api/poc/master-press/admin/bootstrap');
    state.adminBootstrap=data;
    state.adminBootstrapAt=Date.now();
    renderAdmin(data);
    if(data&&data.degraded){
      toast('일시적인 DB 잠금으로 캐시된 관리자 데이터를 표시 중입니다. 잠시 후 자동으로 최신화됩니다.');
    }
    scheduleAdminDetails();
    if(state.pendingCaseProposalDraft){
      var draft=state.pendingCaseProposalDraft;
      state.pendingCaseProposalDraft=null;
      setTimeout(function(){openCase(draft)},0);
    }
  }catch(error){
    if(error.status===401){
      state.isAdmin=false;
      $('adminGate').hidden=false;
      $('adminContent').hidden=true;
    }else{
      // Keep the panel usable even when bootstrap temporarily fails.
      renderBodyBackfillStatus({total_articles:0,blocked_total:0,missing_total:0,processed_today:0,batch_size:0,window_days:7});
      toast('관리 설정 로딩 실패: '+error.message);
    }
  }finally{
    if(shouldShowLoading)hideLoading();
  }
}

